#include <math.h>

/* Sorted ascending a[0..n-1]. Returns index of x or -1. */
int jump_search(const int a[], int n, int x) {
    if (n == 0) return -1;
    int m = (int)sqrt((double)n);          /* block size */
    if (m < 1) m = 1;
    int prev = 0, step = m;
    while (a[(step < n ? step : n) - 1] < x) {
        prev = step;
        step += m;
        if (prev >= n) return -1;          /* x is larger than all */
    }
    int end = step < n ? step : n;
    while (prev < end && a[prev] < x)      /* linear scan inside block */
        prev++;
    return (prev < end && a[prev] == x) ? prev : -1;
}

/* after the hop phase: block is [prev, end) */
int lo = prev, hi = end - 1;
while (lo <= hi) {
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == x) return mid;
    if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
}
return -1;
